-- DISCARD the R&W hard draft versions created by 64 (marked ${MARK}). Drafts only, never published, no attempts can reference them; published sets untouched.
-- generated by scripts/prod-open/sat-rw-hard-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

do $dd$ declare v_n int; begin
  delete from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.readiness_report->>'rwHard1022' = 'true' and not exists (select 1 from mock_exam_attempts a where a.exam_set_id = s.id)
    and exists (select 1 from mock_exam_sets p where p.set_group_id = s.set_group_id and p.status = 'published' and p.version_no < s.version_no);
  get diagnostics v_n = row_count; raise notice 'rw hard drafts removed: %', v_n;
end $dd$;
